WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_d_multi'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '折上折', 'kp-pf-d-multi', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "折上折"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "折扣连乘。每打一次折，就在后面的算式里乘上一个比例。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“全场商品打八折，VIP会员在此基础上再打九折”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这本质上是概率中的“连续抽取”或浓度的“反复倒出”。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{最终售价} = \\text{原价} \\times 80\\% \\times 90\\% = \\text{原价} \\times 72\\%"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、结论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "打八折再打九折，等同于一次性打 七二折。千万不要把 80% 和 90% 去加减！"}]}]}$$ AS jsonb), NULL, '折上折的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "折上折"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_d_multi", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
